function startGame(){
 dist=0;speed=0;playerX=0;steerVel=0;clock=60;lap=1;lapDist=0;elapsed=0;boost=0;particles=[];live=false;counting=true;$('overlay').classList.add('hidden');$('tracktitle').style.opacity='1';$('tracktitle').innerHTML='<strong>COASTLINE SPRINT</strong><span>ONE TRACK · 60 SECONDS · SET YOUR BEST</span>';$('hint').style.opacity='1';$('countdown').style.display='block';$('countdown').textContent='3';
}
